cd /workspace/work && python3 -c "
vals=[float(l.split('=')[1]) for l in open('flip_full.txt') if l.startswith('lavfi')]
fps=120.0
print('frames',len(vals),'dur',round(len(vals)/fps,1))
sig=[(i/fps,v) for i,v in enumerate(vals)]
th=1.2
ev=[];active=False;s=0;pk=0
for t,v in sig:
    if v>th:
        if not active:active=True;s=t;pk=v
        else:pk=max(pk,v)
    else:
        if active:
            if t-s>0.08: ev.append((s,t,pk))
            active=False
merged=[]
for e in ev:
    if merged and e[0]-merged[-1][1]<1.0: merged[-1]=(merged[-1][0],e[1],max(merged[-1][2],e[2]))
    else: merged.append(e)
print('flip events th=1.2:',len(merged))
open('flips.txt','w').write('\n'.join(f'{e[0]:.2f}\t{e[2]:.1f}' for e in merged))
for e in merged: print(f'{e[0]:7.2f}  pk={e[2]:.1f}')
" | head -60

cat > lib.py <<'PYEOF'
def clean_cross(cr, merge=0.28):
    out=[]
    for t in cr:
        if out and t-out[-1]<merge: 
            continue
        out.append(t)
    return out
def load_clusters():
    cl={}
    for l in open('rallies_raw.txt'):
        p=l.rstrip('\n').split('\t')
        cl[p[0]]=[float(x) for x in p[4].split()]
    return cl
PYEOF
python3 -c "
from lib import *
cl=load_clusters()
for rid in sorted(cl,key=lambda r:int(r[1:])):
    c=clean_cross(cl[rid])
    print(f'{rid}\t{len(c)}\t'+' '.join(f'{x:.2f}' for x in c))
" > clean_cross.txt
head -30 clean_cross.txt

